from dispatch.entity_type.models import EntityType
from dispatch.entity.service import find_entities
from dispatch.signal.redaction import MASK
from tests.factories import SignalInstanceFactory


def test_masked_value_never_becomes_entity(session, project):
    # the session token is a secret, so the payload must mask it before entity extraction
    signal_instance = SignalInstanceFactory(
        raw={
            "id": "TEST:1.A/redacted-1",
            "auth": {"session_token": "super-secret-token", "user": "alice"},
        }
    )
    entity_types = [
        EntityType(name="Session token", jpath="auth.session_token", project=project),
    ]

    entities = find_entities(session, signal_instance, entity_types)

    assert entities == []


def test_unmasked_sibling_still_becomes_entity(session, project):
    signal_instance = SignalInstanceFactory(
        raw={
            "id": "TEST:1.A/redacted-2",
            "auth": {"session_token": "super-secret-token", "user": "alice"},
        }
    )
    entity_types = [
        EntityType(name="User", jpath="auth.user", project=project),
    ]

    entities = find_entities(session, signal_instance, entity_types)

    assert [entity.value for entity in entities] == ["alice"]
    assert all(entity.value != MASK for entity in entities)

